import {incrementalRecord} from './incremental-registry.js';
import {annualTextHTML as a} from './annual-localization.js';
import {snpsStubCalculation} from './snps-opening-stub.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>Number.isFinite(x)?x.toLocaleString('en-US',{maximumFractionDigits:3}):'—';
export const SNPS_STUB_NOTE='Selected Q4 2026 cash flows, the 64.9 USDm restructuring settlement and stub WACC remain fixed. Annual edits and simulation affect FY2027 onward with ACT/365.25 fiscal-date discounting; source whole-curve WACC sensitivities differ.';
export const SNPS_CLAIM_NOTE='The residual budget and award units are assumptions. October 31, 2025 awards are assumed unchanged at July 31, 2026; actual July inventory and claim-budget adequacy remain unverified. October information is used. Listed stresses are examples without probabilities; blank means unknown.';
export {SNPS_FUNDING_NOTE} from './snps-opening-stub.js';
export function snpsStubHTML(d,{id=false,detail=false}={}){
 if(d?.ticker!=='SNPS')return '';const s=snpsStubCalculation(d);
 return `<div class="annual-anchor snps-opening-stub"${id?' id="snps-stub-help"':''}><b>${a('Fixed opening fiscal quarter')} · Q4 FY2026 · 2026-08-01–2026-10-31</b><p>${a(SNPS_STUB_NOTE)}</p><p>${a('Selected full-FY2026 forecast reference')}: ${n(d.anchor.revenue)} USDm<br>${a('Mixed FY2026 EBIT reference')}: ${n(d.anchor.EBIT)} USDm · ${a('Actual nine-month earnings plus normalized Q4; not fully normalized annual EBIT.')}</p><p>${a('Fixed Q4 FCFF')}: ${n(s.fcff)} USDm · WACC ${n(s.wacc*100)}% · t = 92 / 365.25 · PV ${n(s.pv)} USDm</p><p class="micro">${a('FY2027 ends October 31, 2027. Annual intervals use actual 365/366-day lengths; terminal value is discounted to the final explicit fiscal date. Past nine-month cash flows are not valued again.')}</p>${detail?`<p>${a('Q4 revenue / EBIT / operating tax / net investment / legacy restructuring settlement')}: ${[s.revenue,s.ebit,s.tax,s.reinvestment,s.legacyRestructuringCash].map(n).join(' / ')} USDm<br>${a('Selected future-new-grant cost rate')}: ${n(s.futureNewGrantRate*100)}% · ${a('already retained in economic EBIT; legacy accounting reversal creates no uplift')}</p>`:''}</div>`;
}
export function snpsAllocationHTML(b,{compact=false}={}){
 if(b?.claimAllocationModel!=='snps-conditional-full-participation-v3'||!b.eligible)return '';
 if(compact)return `<p class="annual-summary-caveat incremental-snps-claim-limits">${a('Residual claim allowance')}: ${n(b.inputs.residualClaimBudget)} USDm · ${a('adequacy unverified')}<br>${a('Allocation units')}: ${n(b.allocationUnits)}m · ${a('award inventory assumed, not reconciled')}<br>${a('Marketable-asset recovery')}: ${n(b.inputs.marketableRecovery*100)}% · ${a('conditional liquidity and tax assumption')}<br>${a('July 31, 2026 origin and cash/common shares; October 31, 2025 assumed awards; October 18, 2026 information. No current-price or as-known comparison.')}${b.unallocatedShortfall>0?`<br><b>${a('Signed pool deficit')}: ${n(b.unallocatedShortfall)} USDm</b>`:''}</p>`;
 return `<p class="annual-summary-caveat snps-allocation-details">${a('Signed pool before assumed award participation')}: ${n(b.equityPoolBeforeExistingEquityClaims)} USDm<br>${a('Common-share allocation')}: ${n(b.equity)} USDm / ${n(b.basicShares)}m<br>${a('Assumed award allocation')}: ${n(b.assumedAwardEquity)} USDm / ${n(b.assumedAwardUnits)}m<br>${a('Total allocation units')}: ${n(b.allocationUnits)}m · ${a('Exercise proceeds')}: 0<br>${a('Options and ESPP use zero-price full participation, not option fair value. Signed source allocation and any deficit are retained. The residual allowance is deducted once; its reference components are not additional claims.')}</p><p>${a(SNPS_CLAIM_NOTE)}</p>`;
}
export function snpsHistoryHTML(d,group){
 const r=incrementalRecord(d?.ticker);if(r?.bridge.type!=='snps-v3')return '';
 const field=group==='growth'?'revenue':group==='profitability'?'operating_income':'capex';
 const label=group==='growth'?'Revenue · USDm':group==='profitability'?'Reported EBIT margin %':'Capex · USDm';
 const note='As-reported annual lens. Software Integrity disposal, Ansys acquisition, ASC 606 and fiscal lengths limit comparisons; these are not organic-growth or forecast bounds. Cash-flow and income-statement perimeters may differ. Both historical lenses and cell sources remain in the evidence report.';
 return `<div class="snps-history-reference"><p class="micro"><b>${a('FY2016–2025 reported reference')}</b> · ${a('Historical observations, not forecast bounds.')}</p><details><summary>${a('Ten-year figures and sources')}</summary><p id="snps-history-${group}-help" class="micro">${a(note)}</p><div class="research-table-scroll"><table class="research-table" aria-describedby="snps-history-${group}-help"><caption>${a('SNPS as-reported annual reference')} · FY2016–2025</caption><thead><tr><th>${a('Fiscal year')}</th><th>${a(label)}</th></tr></thead><tbody>${r.history.map(h=>{const v=group==='growth'?h.revenue:group==='profitability'?h.operatingMargin*100:(h.normalizedValues?.capex??h.capex);const source=h.provenance?.[field]?.url||r.identity.reportPath+'#history';return `<tr><th><a href="${esc(source)}" target="_blank" rel="noopener">${esc(h.fiscalYear)} ↗</a></th><td>${n(v)}</td></tr>`;}).join('')}</tbody></table></div></details></div>`;
}
